INSERT INTO controls(id,framework_id,control_nr,titel,beschrijving,owl_klasse,iri,herkomst,bron_versie,orphan) VALUES('ctrl:CBWControl_16_1','CBW','CBWControl_16_1','CBW-control 16.1 — Vroegtijdige waarschuwing','Bij de vroegtijdige melding verstrekt de entiteit de volgende informatie: indicatie of het incident vermoedelijk door een onrechtmatige of kwaadwillige handeling is veroorzaakt, of het incident grensoverschrijdende gevolgen kan hebben, de contactgegevens van de functionaris die verantwoordelijk is voor de melding, het vermoedelijke tijdstip van de aanvang van het significante incident, zo mogelijk, een beschrijving van de aard en op dat moment merkbare gevolgen van het incident, zo mogelijk, een prognose van de hersteltijd, en zo mogelijk de door de entiteit genomen of voorgenomen maatregelen om de gevolgen van het significante incident te beperken of herhaling hiervan te voorkomen.
